edits.old:
for st in "$st_js" "$st_kagi" "$st_tsu" "$st_mado" "$st_checklist" "$st_claims" "$st_roundgate" "$st_sourcescheck" "$st_citecheck"; do
  case $st in
    0) npass=$((npass + 1)) ;;
    1) nfail=$((nfail + 1)) ;;
    *) nsetup=$((nsetup + 1)) ;;
  esac
done

edits.new:
local tally_once
for tally_once in "$st_js"; do
for st in "$st_js" "$st_kagi" "$st_tsu" "$st_mado" "$st_checklist" "$st_claims" "$st_roundgate" "$st_sourcescheck" "$st_citecheck"; do
  case $st in
    0) npass=$((npass + 1)) ;;
    1) nfail=$((nfail + 1)) ;;
    *) nsetup=$((nsetup + 1)) ;;
  esac
done
done
